shell_commands:
node -e '
const fs = require("node:fs");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
pkg.dependencies = Object.fromEntries(
  Object.entries({...pkg.dependencies, ajv: "^6.15.0"}).sort(([a], [b]) => a.localeCompare(b))
);
fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n");

const lock = JSON.parse(fs.readFileSync("package-lock.json", "utf8"));
lock.packages[""].dependencies = Object.fromEntries(
  Object.entries({...lock.packages[""].dependencies, ajv: "^6.15.0"}).sort(([a], [b]) => a.localeCompare(b))
);
for (const name of ["ajv", "fast-deep-equal", "fast-json-stable-stringify", "json-schema-traverse", "uri-js", "punycode"]) {
  const entry = lock.packages[`node_modules/${name}`];
  if (entry) delete entry.dev;
}
fs.writeFileSync("package-lock.json", JSON.stringify(lock, null, 2) + "\n");
' && git diff package.json package-lock.json
